code.java:
class Solution {
    public int largestPerimeter(int[] nums){
        Arrays.sort(nums);
        for(int i=nums.length-1;i>=2;i--)if(nums[i-1]+nums[i-2]>nums[i])return nums[i]+nums[i-1]+nums[i-2];
        return 0;
    }
}

code.kotlin:
class Solution {
    fun largestPerimeter(nums:IntArray):Int{
        nums.sort();
        for(i in nums.lastIndex downTo 2)if(nums[i-1]+nums[i-2]>nums[i])return nums[i]+nums[i-1]+nums[i-2];
        return 0
    }
}

